# --- dotfiles additions (toshy/slices/user_apps.py) ---------------------------------------

# Zed: its keymap is generated by dotfiles/zed/build.py to behave like on the Mac, assuming
# only Toshy's modifier swap (Cmd -> Ctrl, physical Ctrl -> Super). So let every key Toshy
# would otherwise rewrite in GUI apps (Cmd/Opt arrows, Ctrl emacs keys, ...) reach Zed as-is.
_zed_passthrough = [
    "RC-Left", "RC-Right", "RC-Up", "RC-Down",
    "Shift-RC-Left", "Shift-RC-Right", "Shift-RC-Up", "Shift-RC-Down",
    "Alt-Left", "Alt-Right", "Alt-Shift-Left", "Alt-Shift-Right", "Alt-Shift-g",
    "RC-Backspace", "Alt-Backspace", "Shift-Alt-Backspace", "Super-Backspace",
    "Alt-Delete", "Shift-Alt-Delete", "Super-Delete",
    "Super-a", "Super-e", "Super-b", "Super-f", "Super-n", "Super-p", "Super-k", "Super-d",
    "Super-Tab", "Super-Shift-Tab", "Shift-RC-Left_Brace", "Shift-RC-Right_Brace",
    "RC-Dot", "RC-H",
]
# _hmp_is_zed is defined in the user_custom_functions slice.
keymap("User: Zed - Mac keymap handles these", {
    **{C(combo): C(combo) for combo in _zed_passthrough},
}, when = lambda ctx:
    cnfg.screen_has_focus and
    _hmp_is_zed(ctx)
)

# Cmd+Q closes the focused window (not quit the app) in every app, on KDE and Hyprland: Alt+F4
# is KDE's close-window key and hypr binds it too (dotfiles/keys/keymap.toml: window.close).
# Placed first, so it beats Toshy's per-app Cmd+Q rules (Firefox quit-all, terminals, ...).
keymap("User: Cmd+Q closes window", {
    C("RC-Q"):                  C("Alt-F4"),
}, when = lambda ctx:
    cnfg.screen_has_focus and
    not ctx_app_is_remote
)

# Hyprland: Toshy's default Cmd+Space signal is Super+D, which is also what the physical
# Ctrl+D key sends (Ctrl -> Super), e.g. vim's Ctrl+D in Zed. Use Super+F13 instead, a combo
# no key produces; hypr binds it to the launcher (dotfiles/keys/build.py: TOSHY_SPECIAL).
if DESKTOP_ENV == 'hyprland':
    keymap("User: Hyprland launcher", {
        C("RC-Space"):             [C("Super-F13"), iEF2NT()],
    }, when = lambda ctx:
        cnfg.screen_has_focus and
        not ctx_app_is_remote
    )

